let parsed = $input.first().json.parsed;
let result = [];
if(parsed.length){
  for (const item of parsed) {
    if(item.description != ''){
      result.push({
        title:item.title,
        description: item.description,
        url: item.url
      });
    }
  }
}
if(result.length){
  return {
    status: 'ok',
    data: result
  }
}else{
  return {
    status: 'fail'
  }
}

const returnItems = [];

for (const item of $input.all()) {
  try {
    // Locate the assistant's message in the output array
    const assistantMessage = item.json.output.find(
      msg => msg.role === "assistant" && msg.type === "message"
    );

    if (assistantMessage && assistantMessage.content && assistantMessage.content.length > 0) {
      // Extract the stringified JSON text
      const rawText = assistantMessage.content[0].text;

      // Parse it into a usable JSON object for n8n
      const parsedData = JSON.parse(rawText);

      // Return the parsed data
      returnItems.push({ json: parsedData });
    } else {
      returnItems.push({ json: { error: "Target content not found in the payload." } });
    }
  } catch (error) {
    // Handle parsing errors gracefully
    returnItems.push({ json: { error: error.message } });
  }
}

return returnItems;

let item = $('Loop Over Items').first().json;
let type = $('Prepare Data').first().json.output_type;
if(type == 'image' || type == 'slideshow'){
  let payload = {
      "url": "https://api.kie.ai/api/v1/jobs/createTask",
      "config": {
        "model": "gpt-image-2-5-flare-text-to-image",
         "input": {
            "prompt": item.visual_prompt,
            "aspect_ratio": $('Prepare Data').first().json.output_meta.aspect_ratio.replace('_',':'),
            "resolution": "1K",
            "background": "auto"
         }
      } 
  }
  let related = [];
  if("media_url" in $input.first().json){
    related.push($input.first().json.media_url);
  }
  if(item.selected_image.length > 0){
    for (const img of item.selected_image) {
      related.push(img);
    }
  }  
  if(related.length > 0){
    payload.config.model ='gpt-image-2-5-flare-image-to-image';
    payload.config.input.input_urls = related;
  }

  return payload;
}

let data = [];
let media = [];
for (const item of $('Aggregate').first().json.data) {
